import { QRCodeSVG } from "qrcode.react";
import styles from "./qr-code.module.less";

type Props = {
  /** The string that is encoded into the code, for example a ticket or booking URL */
  value: string;
  /** Draws a solid frame around the code, so it stays readable on a coloured background
   * @defaultValue false */
  withBorder?: boolean;
};

export const QrCode = ({ value, withBorder }: Props) => {
  return <QRCodeSVG value={value} className={styles.qrCode} data-has-border={withBorder} />;
};
